CREATE TABLE "cdr_sync_state" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "cdr_sync_state_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"accountId" text NOT NULL,
	"connectionId" text,
	"accountName" text,
	"highWaterMark" timestamp with time zone,
	"connectionStatus" "cdr_connection_status" DEFAULT 'pending' NOT NULL,
	"lastSyncedAt" timestamp with time zone,
	"lastError" text,
	"createdAt" timestamp with time zone DEFAULT now() NOT NULL,
	"updatedAt" timestamp with time zone,
	CONSTRAINT "cdr_sync_state_accountId_unique" UNIQUE("accountId")
);
